function Chapter12_FrequencyDomainDesignApp
%CHAPTER12_FREQUENCYDOMAINDESIGNAPP Interactive GUI for MEC3079S Chapter 12 — Frequency domain design.
%
%   Run Chapter12_FrequencyDomainDesignApp to open the app. A feedback
%   controller G(s) (P, PI, PD or PID) is shaped in the log-polar plane so
%   that the loop transfer function L(s) = G(s)P(s) avoids the stay-out
%   regions generated by the simplified closed-loop tracking bounds
%
%       M_B <= |T(jw)| <= M_A ,
%
%   where (Chapter 11 / Section 12.2.5)
%       zeta = -ln(%OS/100)/sqrt(pi^2 + ln^2(%OS/100))
%       M_A  = 1/(2 zeta sqrt(1-zeta^2))           (stay-below, all w)
%       w_n  = 4/(zeta T_s),  w_p = w_n sqrt(1-2 zeta^2)
%       M_B  = 0.98                                 (stay-above, w <= w_p)
%
%   Optional steady-state error requirements (Chapter 10, Section 12.2.4):
%     - reference: e_R(inf) <= e_max for a unit step, ramp or parabola, i.e.
%       K_p >= 1/e_max - 1, K_v >= 1/e_max or K_a >= 1/e_max (e_max = 0
%       requires L(s) to be at least Type-1, -2 or -3). For a step, L(j0)
%       must lie on or above the |K_p|_dB line in the log-polar plot.
%     - step-like plant input disturbance: |e_D(inf)| <= e_max with
%       e_D(inf) = -lim 1/(1/P(s) + G(s)) (e_max = 0 requires G(s) to be at
%       least Type-1).
%
%   Controllers (same parameterisation as the notes)
%       P   : G(s) = K
%       PI  : G(s) = K (1 + T_i s)/(T_i s)
%       PD  : G(s) = K (1 + s/alpha)/(1 + s/beta),
%             alpha = w_max / tan((phi_max + pi/2)/2),  beta = w_max^2/alpha
%       PID : G(s) = K (1 + s/alpha)(1 + T_i s) / (s T_i (1 + s/beta))
%
%   Interaction:
%     - Drag the black L(jw) locus in the log-polar plot: up/down changes K,
%       left/right changes T_i (PI) or phi_max (PD/PID), as set by "Drag mode".
%     - The controller Bode diagram marks the PI zero frequency 1/T_i (with the
%       decade above and below it) and the lead frequencies alpha, w_max and beta.
%     - "Freeze design" keeps the current design as G_1(s) (orange, dashed)
%       so that a second design G_2(s) can be compared with it.
%
%   Plants are entered as MATLAB expressions in s, for example
%   10/(s*(s+2)) or 5*exp(-0.01*s)/(1+s/12).
%
%   Requires the Control System Toolbox.

EX = exampleList();

% Design state
S = struct();
S.w       = logspace(-3,3,1500);      % frequency grid (rad/s)
S.P       = tf(1);  S.Pstr = '';  S.Pjw = [];  S.nIntP = 0;  S.exNote = '';
S.OS      = 25;  S.Ts = 5;  S.Mb = 0.98;  S.refQ = 0;  S.essR = Inf;  S.essD = Inf;  S.KpReq = NaN;
S.zeta    = 0; S.wn = 0; S.wp = 1; S.Ma = 1;
S.type    = 'P';  S.formTex = 'K';
S.K       = 1;  S.Ti = 100;  S.wmax = 1;  S.phimax = 0;  S.lockW = true;
S.frozen  = [];
S.drag    = [];
S.busy    = false;
S.cur     = [];
S.ylimLP  = [-50 50];
S.tHeavy  = tic;  S.tFast = tic;  S.tblCache = {};  S.hoverI = 0;

% Colours (bounds as in the notes' figures)
col.cur  = [0.10 0.10 0.10];   % current design  (L_2)
col.frz  = [0.90 0.40 0.05];   % frozen design   (L_1)
col.MA   = [0 0 1];            % stay-below bound (blue, dashed)
col.MB   = [0 0.62 0];         % stay-above bound (green, solid)
col.grid = [0.35 0.35 0.35];
col.ok   = [0.02 0.42 0.12];
col.bad  = [0.70 0.00 0.00];
col.info = [0.30 0.30 0.35];

H = struct();
H.bLP = gobjects(0);  H.bT = gobjects(0);

fig = uifigure('Name','MEC3079S Chapter 12 — Frequency domain design', ...
    'Position',[30 30 1500 900]);
H.fig = fig;
mainGrid = uigridlayout(fig,[1 1],'Padding',[0 0 0 0]);
tg = uitabgroup(mainGrid);

%% =====================================================================
%  Tab 1: Loop-shaping design
%  =====================================================================
t1 = uitab(tg,'Title','Loop-shaping design');
g1 = uigridlayout(t1,[1 2],'ColumnWidth',{360,'1x'});

% Row map of the control column; rows of unused parameters are collapsed
% (info rows show derived values and design hints next to the controls they concern;
% 'fit' lets them grow with their text, which wraps to a varying number of lines)
R = {'hdr',64; 'ex',22; 'P',22; 'OS',22; 'Ts',22; 'Mb',22; 'specInfo','fit'; ...
     'refT',22; 'essR',22; 'essD',22; 'essInfo','fit'; ...
     'typ',22; 'form',44; 'ab','fit'; 'K',22; 'Ti',22; 'W',22; 'lock',22; 'Phi',22; ...
     'drag',22; 'btn',22; 'lead',22; 'leadInfo','fit'; 'frz',22; 'frzInfo','fit'; 'pad','1x'};
c1 = uigridlayout(g1,[size(R,1) 2],'ColumnWidth',{110,'1x'},'RowHeight',R(:,2)', ...
    'RowSpacing',6,'Scrollable','on');

at(uilabel(c1,'Text',['Shape L(s) = G(s)P(s) in the log-polar plane so that it avoids ' ...
    'the stay-out regions of M_B ≤ |T(jω)| ≤ M_A. Drag the black L(jω) locus: ' ...
    'up/down changes K, left/right changes Ti or φ_max.'], ...
    'FontWeight','bold','WordWrap','on'),r('hdr'),[1 2]);

at(uilabel(c1,'Text','Example'),r('ex'),1);
H.ddEx = at(uidropdown(c1,'Items',[{EX.name} {'Custom'}]),r('ex'),2);
at(uilabel(c1,'Text','Plant P(s)'),r('P'),1);
H.edP = at(uieditfield(c1,'text','Tooltip', ...
    'MATLAB expression in s, e.g. 10/(s*(s+2)) or 5*exp(-0.01*s)/(1+s/12). Press Enter to apply.'),r('P'),2);
at(uilabel(c1,'Text','Overshoot %OS'),r('OS'),1);
H.edOS = at(uieditfield(c1,'numeric','Limits',[4.4 90],'Value',S.OS,'Tooltip', ...
    '%OS must exceed 4.33 % so that zeta < 1/sqrt(2) and a resonant peak (M_A > 1, w_p real) exists.'),r('OS'),2);
at(uilabel(c1,'Text','Settling time Ts (s)'),r('Ts'),1);
H.edTs = at(uieditfield(c1,'numeric','Limits',[1e-3 1e4],'Value',S.Ts),r('Ts'),2);
at(uilabel(c1,'Text','Stay-above M_B'),r('Mb'),1);
H.edMb = at(uieditfield(c1,'numeric','Limits',[0.5 0.999],'Value',S.Mb,'Tooltip', ...
    'M_B is chosen heuristically slightly below unity (0.98 in the notes).'),r('Mb'),2);
H.lblSpec = infoLabel('specInfo');
at(uilabel(c1,'Text','Reference (unit)'),r('refT'),1);
H.ddRef = at(uidropdown(c1,'Items',{'Step','Ramp','Parabola'},'ItemsData',{0,1,2},'Tooltip', ...
    'Reference signal used for the steady-state error requirement: r(t) = 1, t or t^2/2.'),r('refT'),2);
at(uilabel(c1,'Text','Ref. error e_R(∞) ≤'),r('essR'),1);
H.edEssR = at(uieditfield(c1,'numeric','Limits',[0 Inf],'Value',S.essR,'ValueDisplayFormat','%.4g', ...
    'Tooltip',['Steady-state tracking error for the reference above (Chapter 10, Section 12.2.4). ' ...
    '0 = zero error; Inf = no requirement.']),r('essR'),2);
at(uilabel(c1,'Text','Dist. error |e_D(∞)| ≤'),r('essD'),1);
H.edEssD = at(uieditfield(c1,'numeric','Limits',[0 Inf],'Value',S.essD,'ValueDisplayFormat','%.4g', ...
    'Tooltip',['Steady-state error caused by a unit step disturbance at the plant input (Section 10.8). ' ...
    '0 = full rejection (G(s) at least Type-1); Inf = no requirement.']),r('essD'),2);
H.lblEss = infoLabel('essInfo');
at(uilabel(c1,'Text','Controller'),r('typ'),1);
H.ddType = at(uidropdown(c1,'Items',{'P','PI','PD','PID'}),r('typ'),2);
H.lblForm = at(uilabel(c1,'Text','','Interpreter','latex','FontSize',14),r('form'),[1 2]);
H.lblAB = infoLabel('ab');
[H.lK,H.gK,H.slK,H.edK]         = paramRow('K','Gain K',[-3 3],[1e-4 1e4],'K');
[H.lTi,H.gTi,H.slTi,H.edTi]     = paramRow('Ti','Integral time Ti',[-2 3],[1e-3 1e4],'Ti');
[H.lW,H.gW,H.slW,H.edW]         = paramRow('W','ω_max (rad/s)',[-2 2],[1e-3 1e3],'wmax');
H.cbLock = at(uicheckbox(c1,'Text','Lock ω_max = ω_p (§12.4.3)','Value',true),r('lock'),2);
[H.lPhi,H.gPhi,H.slPhi,H.edPhi] = paramRow('Phi','φ_max (deg)',[0 85],[0 85],'phimax');
at(uilabel(c1,'Text','Drag mode'),r('drag'),1);
H.ddDrag = at(uidropdown(c1,'Items',{'-'},'Tooltip', ...
    'What dragging the L(jw) locus changes. Up/down always changes K.'),r('drag'),2);
gb = at(uigridlayout(c1,[1 2],'Padding',[0 0 0 0]),r('btn'),[1 2]);
H.btReset = uibutton(gb,'Text','Step 1: start design','Tooltip', ...
    'K = 1, alpha = beta (phi_max = 0), Ti large (100): the starting point used in the notes.');
H.btFinal = uibutton(gb,'Text','Load notes'' final design');
H.btLead = at(uibutton(c1,'Text','Apply suggested lead (ω_max = ω_p, φ_max = Δφ + 10°)'), ...
    r('lead'),[1 2]);
H.lblLead = infoLabel('leadInfo');
gf = at(uigridlayout(c1,[1 2],'Padding',[0 0 0 0]),r('frz'),[1 2]);
H.btFreeze = uibutton(gf,'Text','Freeze design → G₁(s)');
H.btClear = uibutton(gf,'Text','Clear frozen','Enable','off');
H.lblFrz = infoLabel('frzInfo');

% Plots and performance table
gR = uigridlayout(g1,[4 2],'RowHeight',{26,'0.75x','1.25x',295},'ColumnWidth',{'1.2x','1x'});
H.status = at(uilabel(gR,'Text','','FontWeight','bold','FontSize',13),1,1);
% right-hand column: |T(jw)|, controller Bode diagram and step response
gC = at(uigridlayout(gR,[3 1],'Padding',[0 0 0 0],'RowSpacing',8, ...
    'RowHeight',{'1.15x','1.45x',235}),[1 4],2);

ax = at(uiaxes(gR),[2 3],1);
H.axLP = ax;  styleAx(ax);
title(ax,'Log-polar plot of L(j\omega) = G(j\omega)P(j\omega) (drag the black locus)');
xlabel(ax,'\angle L(j\omega) (deg)');  ylabel(ax,'|L(j\omega)| (dB)');
ax.XTick = -1080:45:360;  ax.YLim = S.ylimLP;  ax.XLim = [-360 0];
ax.ButtonDownFcn = @(~,~) onLPdown();
H.Lf     = plot(ax,NaN,NaN,'--','Color',col.frz,'LineWidth',2,'Visible','off','PickableParts','none');
H.L      = plot(ax,NaN,NaN,'-','Color',col.cur,'LineWidth',2.5,'ButtonDownFcn',@(~,~) onLPdown());
H.Lfwp   = plot(ax,NaN,NaN,'o','MarkerFaceColor',col.MB,'MarkerEdgeColor',col.frz,'MarkerSize',8, ...
                'LineWidth',1.5,'Visible','off','PickableParts','none');
H.Lwp    = plot(ax,NaN,NaN,'o','MarkerFaceColor',col.MB,'MarkerEdgeColor','k','MarkerSize',9,'PickableParts','none');
H.LwpTxt = text(ax,NaN,NaN,'   L(j\omega_p)','PickableParts','none');
H.crit   = plot(ax,-180,0,'ro','MarkerFaceColor','r','MarkerSize',7,'PickableParts','none');
H.ylKp   = yline(ax,0,'--k','|K_p|_{dB} (stay above)','LabelHorizontalAlignment','left', ...
                'LineWidth',1.5,'Visible','off','PickableParts','none');
H.L0     = plot(ax,NaN,NaN,'o','MarkerFaceColor',[0 0.45 0.74],'MarkerEdgeColor','k','MarkerSize',9, ...
                'PickableParts','none');
H.dragPt = plot(ax,NaN,NaN,'s','MarkerSize',11,'MarkerEdgeColor',[0.9 0.1 0.1],'LineWidth',2,'PickableParts','none');
H.hoverTxt = text(ax,NaN,NaN,'','BackgroundColor',[1 1 0.88],'EdgeColor',[0.7 0.7 0.7], ...
                'Margin',3,'PickableParts','none','VerticalAlignment','bottom');

ax = at(uiaxes(gC),1,1);
H.axT = ax;  styleAx(ax);  ax.XScale = 'log';
title(ax,'Closed-loop magnitude, |T(j\omega)| = |L(j\omega)/[1 + L(j\omega)]|');
H.TpkTxt = subtitle(ax,' ');
ylabel(ax,'|T(j\omega)| (dB)');  xlabel(ax,'Frequency (rad/s)');
H.Tf  = plot(ax,NaN,NaN,'--','Color',col.frz,'LineWidth',1.8,'Visible','off');
H.T   = plot(ax,NaN,NaN,'-','Color',col.cur,'LineWidth',2);
H.TpkLine = plot(ax,NaN,NaN,'-.','Color',[0.35 0.35 0.38],'LineWidth',1.2);

% Controller Bode diagram: the PI zero frequency (with the decade above and below)
% and the lead frequencies alpha, w_max and beta are marked as in the notes' figures
% (a tiled layout keeps the magnitude and phase axes aligned on the left)
pG = at(uipanel(gC,'BorderType','none'),2,1);
tlG = tiledlayout(pG,21,1,'TileSpacing','tight','Padding','tight');
H.axGm = nexttile(tlG,[11 1]);  H.axGp = nexttile(tlG,[10 1]);
for ax = [H.axGm H.axGp], styleAx(ax);  ax.XScale = 'log';  ax.FontUnits = 'pixels';  ax.FontSize = 12; end   % as uiaxes
title(H.axGm,'Controller Bode diagram, G(j\omega)');
H.GinfoTxt = subtitle(H.axGm,' ');
ylabel(H.axGm,'|G(j\omega)| (dB)');
ylabel(H.axGp,'\angle G(j\omega) (deg)');  xlabel(H.axGp,'Frequency (rad/s)');
H.axGm.XTickLabel = {};
linkaxes([H.axGm H.axGp],'x');
H.Gmf = plot(H.axGm,NaN,NaN,'--','Color',col.frz,'LineWidth',1.8,'Visible','off');
H.Gpf = plot(H.axGp,NaN,NaN,'--','Color',col.frz,'LineWidth',1.8,'Visible','off');
H.Gm  = plot(H.axGm,NaN,NaN,'-','Color',col.cur,'LineWidth',2);
H.Gp  = plot(H.axGp,NaN,NaN,'-','Color',col.cur,'LineWidth',2);
% frequency markers: [magnitude axes (labelled), phase axes]
gxName = {'wp','z','zlo','zhi','a','wm','b'};
gxCol  = {col.MB,'k','k','k',[0.55 0 0.6],[0.85 0.1 0.1],[0.55 0 0.6]};
gxSty  = {':','--',':',':','--','-.','--'};
gxSide = {'left','left','right','right','right','left','right'};   % label side, to limit overlaps
for k = 1:numel(gxName)
    H.gx.(gxName{k}) = [xline(H.axGm,1,gxSty{k},'Color',gxCol{k},'LineWidth',1.2,'Visible','off', ...
                             'LabelVerticalAlignment','top','LabelOrientation','horizontal', ...
                             'LabelHorizontalAlignment',gxSide{k},'FontSize',10) ...
                       xline(H.axGp,1,gxSty{k},'Color',gxCol{k},'LineWidth',1.2,'Visible','off')];
end
H.ylGK   = yline(H.axGm,0,':','Color',[0.4 0.4 0.4],'LineWidth',1.1,'LabelHorizontalAlignment','left', ...
                 'LabelVerticalAlignment','top','FontSize',10);
H.ylGhf  = yline(H.axGm,0,':','Color',[0.55 0 0.6],'LineWidth',1.1,'LabelHorizontalAlignment','right', ...
                 'LabelVerticalAlignment','top','FontSize',10,'Visible','off');
H.ylGphi = yline(H.axGp,0,':','Color',[0.85 0.1 0.1],'LineWidth',1.1,'LabelHorizontalAlignment','left', ...
                 'LabelVerticalAlignment','bottom','FontSize',10,'Visible','off');
H.GmPt = plot(H.axGm,NaN,NaN,'o','MarkerSize',7,'MarkerFaceColor',[0.85 0.1 0.1],'MarkerEdgeColor','k');
H.GpPt = plot(H.axGp,NaN,NaN,'o','MarkerSize',7,'MarkerFaceColor',[0.85 0.1 0.1],'MarkerEdgeColor','k');
for k = 1:2
    H.GmTxt(k) = text(H.axGm,NaN,NaN,'','FontSize',10,'VerticalAlignment','top','Color',[0.6 0 0]);
    H.GpTxt(k) = text(H.axGp,NaN,NaN,'','FontSize',10,'VerticalAlignment','top','Color',[0.6 0 0]);
end

H.tbl = at(uitable(gR,'ColumnName',{'Metric','Specification','Current','Frozen'}, ...
    'RowName',{},'ColumnWidth',{'6x','5x','5x','5x'}),4,1);
H.stOK   = uistyle('BackgroundColor',[0.88 0.96 0.88],'FontColor',[0 0.40 0]);
H.stBad  = uistyle('BackgroundColor',[0.99 0.89 0.89],'FontColor',col.bad);
H.stName = uistyle('FontWeight','bold');

ax = at(uiaxes(gC),3,1);
H.axY = ax;  styleAx(ax);
title(ax,'Closed-loop step response');
xlabel(ax,'Time (s)');  ylabel(ax,'y(t)');
H.Yf   = plot(ax,NaN,NaN,'--','Color',col.frz,'LineWidth',1.8,'Visible','off');
H.Y    = plot(ax,NaN,NaN,'-','Color',col.cur,'LineWidth',2);
H.Ypk  = plot(ax,NaN,NaN,'v','MarkerSize',9,'MarkerFaceColor',col.MA,'MarkerEdgeColor','k');
H.YpkTxt = text(ax,NaN,NaN,'','VerticalAlignment','bottom','Color',col.MA);
H.Yts  = plot(ax,NaN,NaN,'o','MarkerSize',8,'MarkerFaceColor',[0.9 0.1 0.1],'MarkerEdgeColor','k');
H.YtsTxt = text(ax,NaN,NaN,'','VerticalAlignment','top','Color',[0.75 0 0]);
H.Yunst = text(ax,0.5,0.5,'','Units','normalized','HorizontalAlignment','center','FontSize',16, ...
               'Color',col.bad,'FontWeight','bold');
H.ylOS = yline(ax,1.25,'--b','%OS','LabelHorizontalAlignment','center');
H.ylP2 = yline(ax,1.02,'--r','+2%','LabelHorizontalAlignment','right');
H.ylM2 = yline(ax,0.98,'--r','-2%','LabelHorizontalAlignment','right','LabelVerticalAlignment','bottom');
H.xlTs = xline(ax,5,'--r','t_s','LabelVerticalAlignment','bottom');

%% =====================================================================
%  Tab 2: Methodology
%  =====================================================================
t2 = uitab(tg,'Title','Methodology');
g2 = uigridlayout(t2,[1 1]);
H.txtMethod = uitextarea(g2,'Editable','off','FontSize',13);

% Callbacks
H.ddEx.ValueChangedFcn = @(src,~) loadExample(src.Value);
H.edP.ValueChangedFcn = @(~,~) onCustomPlant();
H.edOS.ValueChangedFcn = @(src,~) onSpec('OS',src.Value);
H.edTs.ValueChangedFcn = @(src,~) onSpec('Ts',src.Value);
H.edMb.ValueChangedFcn = @(src,~) onSpec('Mb',src.Value);
H.ddRef.ValueChangedFcn = @(src,~) onSpec('refQ',src.Value);
H.edEssR.ValueChangedFcn = @(src,~) onSpec('essR',src.Value);
H.edEssD.ValueChangedFcn = @(src,~) onSpec('essD',src.Value);
H.ddType.ValueChangedFcn = @(src,~) onType(src.Value);
H.cbLock.ValueChangedFcn = @(src,~) onLock(src.Value);
H.btReset.ButtonPushedFcn = @(~,~) onResetStep1();
H.btFinal.ButtonPushedFcn = @(~,~) onLoadFinal();
H.btLead.ButtonPushedFcn = @(~,~) onSuggestLead();
H.btFreeze.ButtonPushedFcn = @(~,~) onFreeze();
H.btClear.ButtonPushedFcn = @(~,~) onClearFrozen();
fig.WindowButtonMotionFcn = @(~,~) onHover();

% Initial draw
drawnow;
loadExample(EX(1).name);

%% =====================================================================
%  Layout helpers
%  =====================================================================
    function k = r(name)
        k = find(strcmp(R(:,1),name),1);
    end

    function h = infoLabel(row)
        % Small wrapped label spanning the control column, for derived values and hints.
        h = at(uilabel(c1,'Text','','WordWrap','on','FontSize',11,'FontColor',col.info, ...
            'VerticalAlignment','top'),r(row),[1 2]);
    end

    function [lbl,g,sl,ed] = paramRow(row,name,slLim,edLim,key)
        % Label, slider and numeric field for one controller parameter.
        lbl = at(uilabel(c1,'Text',name),r(row),1);
        g = at(uigridlayout(c1,[1 2],'ColumnWidth',{'1x',70},'Padding',[0 0 0 0]),r(row),2);
        sl = uislider(g,'Limits',slLim,'MajorTicks',[],'MinorTicks',[], ...
            'ValueChangingFcn',@(~,evt) setParam(key,slider2val(key,evt.Value),false), ...
            'ValueChangedFcn',@(src,~) setParam(key,slider2val(key,src.Value),true));
        ed = uieditfield(g,'numeric','Limits',edLim,'ValueDisplayFormat','%.4g', ...
            'ValueChangedFcn',@(src,~) setParam(key,src.Value,true));
    end

%% =====================================================================
%  Callbacks
%  =====================================================================
    function loadExample(name)
        H.ddEx.Value = name;
        i = find(strcmp({EX.name},name),1);
        if isempty(i)            % custom plant
            S.exNote = 'Custom plant: type P(s) in the Plant field and press Enter.';
            H.btFinal.Enable = 'off';
            updateMethodText();
            focus(H.edP);
            return
        end
        E = EX(i);
        if ~isempty(S.frozen), onClearFrozen(); end   % frozen design belongs to the previous plant
        setPlant(parseTF(E.Pstr),E.Pstr);
        S.OS = E.OS;  S.Ts = E.Ts;  S.Mb = 0.98;
        S.refQ = E.refQ;  S.essR = E.essR;  S.essD = E.essD;
        H.edOS.Value = S.OS;  H.edTs.Value = S.Ts;  H.edMb.Value = S.Mb;
        H.ddRef.Value = S.refQ;  H.edEssR.Value = S.essR;  H.edEssD.Value = S.essD;
        S.exNote = E.note;
        S.type = E.type;
        resetStep1Values();
        H.btFinal.Enable = onoff(~isempty(E.final));
        updateSpecs(false);
        onType(S.type);
    end

    function onCustomPlant()
        str = strtrim(H.edP.Value);
        try
            P = parseTF(str);
        catch ME
            uialert(fig,ME.message,'Invalid transfer function');
            return
        end
        if ~isempty(S.frozen), onClearFrozen(); end
        setPlant(P,str);
        H.ddEx.Value = 'Custom';
        S.exNote = sprintf('Custom plant P(s) = %s.  Specifications: %%OS = %g %%, T_s = %g s.',str,S.OS,S.Ts);
        H.btFinal.Enable = 'off';
        updateMethodText();
        refresh(true);
    end

    function setPlant(P,str)
        S.P = P;
        S.Pstr = str;
        S.Pjw = reshape(squeeze(freqresp(P,S.w)),1,[]);
        p = pole(P);  z = zero(P);
        S.nIntP = sum(abs(p) < 1e-9) - sum(abs(z) < 1e-9);
        H.edP.Value = str;
    end

    function onSpec(name,val)
        S.(name) = val;
        updateSpecs(true);
    end

    function updateSpecs(doRefresh)
        x = log(S.OS/100);
        S.zeta = -x/sqrt(pi^2 + x^2);
        S.wn   = 4/(S.zeta*S.Ts);
        S.wp   = S.wn*sqrt(1 - 2*S.zeta^2);
        S.Ma   = 1/(2*S.zeta*sqrt(1 - S.zeta^2));
        if S.lockW, S.wmax = S.wp; end
        H.lblSpec.Text = sprintf(['ζ = %.4f,  ω_n = 4/(ζT_s) = %.4g rad/s,  ' ...
            'ω_p = ω_n√(1−2ζ²) = %.4g rad/s,  M_A = %.4f'],S.zeta,S.wn,S.wp,S.Ma);
        % Section 12.2.4: required position error constant for a step error spec
        S.KpReq = NaN;
        if S.refQ == 0, S.KpReq = errorConstantRequired(0,S.essR); end
        if isfinite(S.KpReq) && S.KpReq > 0
            set(H.ylKp,'Value',20*log10(S.KpReq),'Visible','on', ...
                'Label',sprintf('|K_p|_{dB} = %.3g dB (stay above)',20*log10(S.KpReq)));
        else
            H.ylKp.Visible = 'off';
        end
        drawBoundsLP();
        drawBoundsT();
        if doRefresh, refresh(true); end
    end

    function onType(t)
        S.type = t;
        H.ddType.Value = t;
        isTi = any(strcmp(t,{'PI','PID'}));  isLead = any(strcmp(t,{'PD','PID'}));
        rh = R(:,2)';
        hide = {};
        if ~isTi,   hide = [hide {'Ti'}]; end
        if ~isLead, hide = [hide {'ab','W','lock','Phi','lead','leadInfo'}]; end
        for k = 1:numel(hide), rh{r(hide{k})} = 0; end
        c1.RowHeight = rh;
        setVis({H.lTi H.gTi}, isTi);
        setVis({H.lblAB H.lW H.gW H.cbLock H.lPhi H.gPhi H.btLead H.lblLead}, isLead);
        switch t
            case 'P'
                S.formTex = 'K';
                items = {'Gain K (up/down)'};  data = {'K'};
            case 'PI'
                S.formTex = 'K\,\frac{1+sT_i}{sT_i}';
                items = {'K (up/down) + Ti (left/right)','Gain K only (up/down)'};  data = {'Ti','K'};
            case 'PD'
                S.formTex = 'K\,\frac{1+s/\alpha}{1+s/\beta}';
                items = {'K (up/down) + φ_max (left/right)','Gain K only (up/down)'};  data = {'lead','K'};
            case 'PID'
                S.formTex = 'K\,\frac{(1+s/\alpha)(1+sT_i)}{sT_i\,(1+s/\beta)}';
                items = {'K (up/down) + φ_max (left/right)','K (up/down) + Ti (left/right)', ...
                    'Gain K only (up/down)'};
                data = {'lead','Ti','K'};
        end
        H.ddDrag.Items = items;  H.ddDrag.ItemsData = data;  H.ddDrag.Value = data{1};
        updateMethodText();
        refresh(true);
    end

    function onLock(v)
        S.lockW = v;
        if v, S.wmax = S.wp; end
        refresh(true);
    end

    function setParam(key,val,final)
        switch key
            case 'K',      S.K = clamp(val,1e-4,1e4);
            case 'Ti',     S.Ti = clamp(val,1e-3,1e4);
            case 'wmax',   S.wmax = clamp(val,1e-3,1e3);  S.lockW = false;
            case 'phimax', S.phimax = clamp(val,0,85);
        end
        if ~final && toc(S.tFast) < 0.03, return; end   % drop events that arrive faster than we draw
        refresh(final);
        if ~final, drawnow limitrate nocallbacks; end
        S.tFast = tic;
    end

    function v = slider2val(key,x)
        if strcmp(key,'phimax'), v = x; else, v = 10^x; end
    end

    function onResetStep1()
        resetStep1Values();
        refresh(true);
    end

    function resetStep1Values()
        S.K = 1;  S.Ti = 100;  S.phimax = 0;  S.lockW = true;  S.wmax = S.wp;
    end

    function onLoadFinal()
        i = find(strcmp({EX.name},H.ddEx.Value),1);
        if isempty(i) || isempty(EX(i).final), return; end
        f = EX(i).final;
        resetStep1Values();
        S.type = EX(i).type;
        if isfield(f,'K'),      S.K = f.K; end
        if isfield(f,'Ti'),     S.Ti = f.Ti; end
        if isfield(f,'phimax'), S.phimax = f.phimax; end
        S.lockW = true;  S.wmax = S.wp;
        onType(S.type);
    end

    function onSuggestLead()
        need = requiredLead();
        S.lockW = true;  S.wmax = S.wp;
        S.phimax = clamp(need + 10,0,80);
        refresh(true);
    end

    function onFreeze()
        if isempty(S.cur), return; end
        F = S.cur;
        F.type = S.type;
        F.desc = controllerStr();
        S.frozen = F;
        H.btClear.Enable = 'on';
        set([H.Lf H.Lfwp H.Tf H.Gmf H.Gpf],'Visible','on');
        set(H.Lf,'XData',F.ph,'YData',F.mag);
        set(H.Tf,'XData',S.w,'YData',F.Tmag);
        set(H.Gmf,'XData',S.w,'YData',F.Gmag);
        set(H.Gpf,'XData',S.w,'YData',F.Gph);
        set(H.Yf,'XData',F.t,'YData',F.y);
        H.Yf.Visible = onoff(F.stable);     % an unstable frozen response is not plotted
        rebuildLegends();
        refresh(true);
    end

    function onClearFrozen()
        S.frozen = [];
        H.btClear.Enable = 'off';
        set([H.Lf H.Lfwp H.Tf H.Gmf H.Gpf H.Yf],'Visible','off');
        rebuildLegends();
        refresh(true);
    end

%% =====================================================================
%  Dragging the L(jw) locus
%  =====================================================================
    function pt = mousePoint(ax)
        % TestPoint in fig.UserData lets scripted tests stand in for the mouse.
        if isstruct(fig.UserData) && isfield(fig.UserData,'TestPoint')
            pt = fig.UserData.TestPoint;
        else
            pt = ax.CurrentPoint(1,1:2);
        end
    end

    function onLPdown()
        if isempty(S.cur), return; end
        cp = mousePoint(H.axLP);
        [i,d] = nearestLocus(cp);
        if d > 0.045, return; end
        D = struct();
        D.i = i;  D.w = S.w(i);  D.Pjw = S.Pjw(i);
        D.x0 = cp(1);  D.y0 = cp(2);
        D.ph0 = S.cur.ph(i);  D.mag0 = S.cur.mag(i);
        D.K0 = S.K;  D.Ti0 = S.Ti;  D.phimax0 = S.phimax;
        D.mode = H.ddDrag.Value;
        if S.lockW, D.wm = S.wp; else, D.wm = S.wmax; end
        S.drag = D;
        fig.Pointer = 'fleur';
        fig.WindowButtonMotionFcn = @(~,~) onDragMove();
        fig.WindowButtonUpFcn     = @(~,~) onDragUp();
        set(H.hoverTxt,'String','');
        set(H.dragPt,'XData',D.ph0,'YData',D.mag0);
    end

    function onDragMove()
        % Motion events that queue up while a frame is being drawn are dropped, so the
        % locus always follows the latest cursor position without lagging behind.
        if isempty(S.drag) || S.busy || toc(S.tFast) < 0.03, return; end
        S.busy = true;
        cp = mousePoint(H.axLP);
        dragTo(cp(1)-S.drag.x0, cp(2)-S.drag.y0);
        refresh(false);
        showDragPoint();
        drawnow limitrate nocallbacks;
        S.busy = false;
        S.tFast = tic;
    end

    function showDragPoint()
        D = S.drag;
        if isempty(D) || isempty(S.cur), return; end
        set(H.dragPt,'XData',S.cur.ph(D.i),'YData',S.cur.mag(D.i));
        set(H.hoverTxt,'Position',[S.cur.ph(D.i) S.cur.mag(D.i)+2 0], ...
            'String',sprintf(' \\omega = %.3g rad/s ',D.w));
    end

    function dragTo(dx,dy)
        D = S.drag;
        targetMag = D.mag0 + dy;
        switch D.mode
            case 'Ti'       % horizontal: PI phase lag at w*  ->  T_i
                phI0 = -atand(1/(D.w*D.Ti0));
                phI  = clamp(phI0 + dx,-89.5,-0.03);
                S.Ti = clamp(1/(D.w*tand(-phI)),1e-3,1e4);
            case 'lead'     % horizontal: lead phase at w*  ->  phi_max
                S.wmax = D.wm;
                target = leadPhase(D.w,D.wm,D.phimax0) + dx;
                S.phimax = solvePhimax(D.w,D.wm,target);
        end
        % vertical: choose K so that |L(jw*)| follows the cursor
        Gu = controllerUnitK(D.w);
        m1 = 20*log10(abs(D.Pjw*Gu));
        S.K = clamp(10^((targetMag - m1)/20),1e-4,1e4);
    end

    function onDragUp()
        if ~isempty(S.drag)                    % apply the release position exactly
            cp = mousePoint(H.axLP);
            dragTo(cp(1)-S.drag.x0, cp(2)-S.drag.y0);
        end
        S.drag = [];  S.busy = false;
        fig.WindowButtonMotionFcn = @(~,~) onHover();
        fig.WindowButtonUpFcn = '';
        fig.Pointer = 'arrow';
        set(H.dragPt,'XData',NaN,'YData',NaN);
        set(H.hoverTxt,'String','');
        refresh(true);
    end

    function onHover()
        if ~isempty(S.drag) || isempty(S.cur), return; end
        cp = mousePoint(H.axLP);
        xl = H.axLP.XLim;  yl = H.axLP.YLim;
        inAx = cp(1)>=xl(1) && cp(1)<=xl(2) && cp(2)>=yl(1) && cp(2)<=yl(2);
        if inAx
            [i,d] = nearestLocus(cp);
            if d < 0.045
                if ~strcmp(fig.Pointer,'hand'), fig.Pointer = 'hand'; end
                if i == S.hoverI, return; end
                S.hoverI = i;
                set(H.hoverTxt,'Position',[S.cur.ph(i) S.cur.mag(i)+2 0], ...
                    'String',sprintf(' \\omega = %.3g rad/s, drag to reshape L(j\\omega) ',S.w(i)));
                return
            end
        end
        S.hoverI = 0;
        if ~strcmp(fig.Pointer,'arrow'), fig.Pointer = 'arrow'; end
        if ~isempty(H.hoverTxt.String), set(H.hoverTxt,'String',''); end
    end

    function [i,d] = nearestLocus(cp)
        xl = H.axLP.XLim;  yl = H.axLP.YLim;
        dd = ((S.cur.ph - cp(1))/diff(xl)).^2 + ((S.cur.mag - cp(2))/diff(yl)).^2;
        [d,i] = min(dd);  d = sqrt(d);
    end

%% =====================================================================
%  Computation
%  =====================================================================
    function refresh(final)
        % final = false while dragging / sliding: the plots update on every event,
        % while the margins, table, status and results are refreshed at most ~3x/s.
        try
            heavy = final || toc(S.tHeavy) > 0.3;
            compute(heavy);
            updatePlots(final);
            updateControls();
            if heavy
                updateTable();
                updateStatus();
                updateInfo();
                S.tHeavy = tic;
            end
        catch ME
            H.status.Text = ['Error: ' ME.message];
            H.status.FontColor = col.bad;
        end
    end

    function compute(withMargins)
        C = struct();
        [Gjw,G] = controllerResponse(S.w);
        Ljw  = S.Pjw.*Gjw;
        C.mag = 20*log10(abs(Ljw));
        ph = unwrap(angle(Ljw))*180/pi;
        nInt = S.nIntP + any(strcmp(S.type,{'PI','PID'}));
        rr   = Ljw(1)*(1i*S.w(1))^nInt;
        ref  = -90*nInt - 180*(real(rr) < 0);
        C.ph = ph + 360*round((ref - ph(1))/360);
        Tjw  = Ljw./(1 + Ljw);
        C.Tabs = abs(Tjw);
        C.Tmag = 20*log10(C.Tabs);
        C.Gmag = 20*log10(abs(Gjw));
        C.Gph  = unwrap(angle(Gjw))*180/pi;
        [C.MpT,ipk] = max(C.Tabs);  C.wpk = S.w(ipk);
        C.G = G;
        Ltf = S.P*G;
        % Steady-state errors (Chapter 10): reference r = t^q/q!, unit step disturbance
        C.k  = typeAndGain(Ltf);
        C.Kp = limGain(Ltf,0);
        C.Kq = limGain(Ltf,S.refQ);           % K_p, K_v or K_a
        if S.refQ == 0, C.eR = 1/(1 + C.Kq); else, C.eR = 1/C.Kq; end
        C.Pdc = limGain(S.P,0);
        C.Gdc = limGain(G,0);
        C.kG  = typeAndGain(G);
        C.eD  = -1/(1/C.Pdc + C.Gdc);
        T = feedback(Ltf,1);
        C.stable = clStable(T);
        % The margins are shown in the table, so they are recomputed whenever the
        % table is (also while dragging), not only when the interaction ends.
        if withMargins || isempty(S.cur)
            ws = warning('off','all');
            try
                [Gm,Pm,Wcg,Wcp] = margin(Ltf);
            catch
                Gm = NaN; Pm = NaN; Wcg = NaN; Wcp = NaN;
            end
            warning(ws);
        else
            Gm = S.cur.Gm; Pm = S.cur.Pm; Wcg = S.cur.Wcg; Wcp = S.cur.Wcp;
        end
        C.Gm = Gm;  C.Pm = Pm;  C.Wcg = Wcg;  C.Wcp = Wcp;
        % step response
        C.OS = NaN;  C.TsAct = NaN;  C.Tpk = NaN;  C.Ypk = NaN;  C.yss = NaN;
        if C.stable
            C.yss = dcgain(T);
            % let step() choose the sample time from the closed-loop dynamics (accurate
            % for fast and slow systems alike)
            tEnd = 2.5*S.Ts;
            [y,t] = step(T,tEnd);  info = stepinfo(y,t,C.yss,'SettlingTimeThreshold',0.02);
            if isnan(info.SettlingTime) || info.SettlingTime > 0.9*tEnd
                tEnd = 10*S.Ts;
                [y,t] = step(T,tEnd);  info = stepinfo(y,t,C.yss,'SettlingTimeThreshold',0.02);
            end
            C.OS = info.Overshoot;  C.TsAct = info.SettlingTime;
            C.Tpk = info.PeakTime;  C.Ypk = info.Peak;
            if C.yss < 0, C.Ypk = NaN; end
        else
            t = linspace(0,2*S.Ts,400);
            try, y = step(T,t); catch, y = NaN(size(t)); end
        end
        C.t = t(:).';  C.y = y(:).';
        C.Ghf = highFreqGain();
        S.cur = C;
    end

    function [Gjw,G] = controllerResponse(w)
        % Frequency response G(jw) (fast, used while dragging) and, if requested,
        % the transfer function G(s) built from polynomial coefficients.
        jw = 1i*w;  num = S.K;  den = 1;
        Gjw = S.K*ones(size(w));
        if any(strcmp(S.type,{'PD','PID'})) && S.phimax > 1e-6
            [a,b] = leadAB(S.wmax,S.phimax);
            Gjw = Gjw.*(1 + jw/a)./(1 + jw/b);
            num = conv(num,[1/a 1]);  den = conv(den,[1/b 1]);
        end
        if any(strcmp(S.type,{'PI','PID'}))
            Gjw = Gjw.*(1 + jw*S.Ti)./(jw*S.Ti);
            num = conv(num,[S.Ti 1]);  den = conv(den,[S.Ti 0]);
        end
        if nargout > 1, G = tf(num,den); end
    end

    function g = controllerUnitK(w)
        Kk = S.K;  S.K = 1;
        g = controllerResponse(w);
        S.K = Kk;
    end

    function g = highFreqGain()
        g = S.K;
        if any(strcmp(S.type,{'PD','PID'})) && S.phimax > 1e-6
            [a,b] = leadAB(S.wmax,S.phimax);  g = S.K*b/a;
        end
    end

    function [need,wAt] = requiredLead()
        % Section 12.4.3: measure on the log-polar plot how much phase lead is needed to
        % move the L(jw) locus (without the lead filter) out of the M_A stay-out region.
        % For every point inside the region, the horizontal distance to the region's
        % right-hand boundary at the same magnitude is computed; the largest one is used.
        wAt = NaN;
        th = S.cur.ph - leadPhaseCur(S.w);           % phase of L without lead (deg)
        m  = 10.^((S.cur.mag - leadGainDbCur(S.w))/20);
        c  = (m.^2/S.Ma^2 - 1 - m.^2)./(2*m);        % cos(angle) on the M_A contour
        ok = c > -1 & isfinite(c);
        if ~any(ok), need = 0; return; end
        c  = min(c,1);
        k  = round((th + 180)/360);
        thR = -acosd(c) + 360*k;                     % right-hand boundary
        thL = -360 + acosd(c) + 360*k;               % left-hand boundary
        inside = ok & th > thL & th < thR;
        if ~any(inside), need = 0; return; end
        d = thR - th;  d(~inside) = -Inf;
        [need,i] = max(d);
        wAt = S.w(i);
    end

    function g = leadGainDbCur(w)
        if any(strcmp(S.type,{'PD','PID'})) && S.phimax > 1e-6
            [a,b] = leadAB(S.wmax,S.phimax);
            g = 20*log10(abs(1 + 1i*w/a)./abs(1 + 1i*w/b));
        else
            g = 0;
        end
    end

    function p = leadPhaseCur(w)
        if any(strcmp(S.type,{'PD','PID'})) && S.phimax > 1e-6
            p = leadPhase(w,S.wmax,S.phimax);
        else
            p = 0;
        end
    end

%% =====================================================================
%  Plots
%  =====================================================================
    function drawBoundsLP()
        delete(H.bLP(isgraphics(H.bLP)));  H.bLP = gobjects(0);
        ax = H.axLP;
        offs = [-720 -360 0 360];
        % ---- other |T(jw)| contours (semi-transparent dashed)
        Mdb = [12 6 3 1 0.5 0 -1 -3 -6 -12 -20];
        for o = offs
            for m = Mdb
                [x,y] = mContour(10^(m/20));
                h = patch(ax,'XData',[x+o NaN],'YData',[y NaN],'FaceColor','none', ...
                    'EdgeColor',col.grid,'EdgeAlpha',0.35,'LineStyle','--','LineWidth',0.7,'PickableParts','none');
                H.bLP(end+1) = h; %#ok<AGROW>
                if o == 0 && m == Mdb(1), H.contourLeg = h; end
                if o == 0
                    sel = y > S.ylimLP(1)+1 & y < S.ylimLP(2)-1 & x > -359 & x < -1;
                    if any(sel)
                        xs = x(sel);  ys = y(sel);
                        if m > 0, [~,j] = max(ys); ha = 'center'; va = 'bottom';
                        else,     [~,j] = min(abs(xs + 25)); ha = 'left'; va = 'middle'; end
                        H.bLP(end+1) = text(ax,xs(j),ys(j),sprintf(' %g dB',m),'FontSize',8, ...
                            'Color',[0.5 0.5 0.5],'PickableParts','none','HorizontalAlignment',ha, ...
                            'VerticalAlignment',va); %#ok<AGROW>
                    end
                end
            end
        end
        % ---- stay-out regions
        [xA,yA] = mContour(S.Ma);
        [xB,yB] = mContour(S.Mb);
        for o = offs
            H.bLP(end+1) = patch(ax,'XData',[xB+o, o, o-360],'YData',[yB, -500, -500], ...
                'FaceColor',col.MB,'FaceAlpha',0.08,'EdgeColor','none','PickableParts','none'); %#ok<AGROW>
            H.bLP(end+1) = patch(ax,'XData',xA+o,'YData',yA, ...
                'FaceColor',col.MA,'FaceAlpha',0.09,'EdgeColor','none','PickableParts','none'); %#ok<AGROW>
            hb = plot(ax,xB+o,yB,'-','Color',col.MB,'LineWidth',2,'PickableParts','none');
            ha = plot(ax,xA+o,yA,'--','Color',col.MA,'LineWidth',2,'PickableParts','none');
            H.bLP(end+1) = hb;  H.bLP(end+1) = ha; %#ok<AGROW>
            if o == 0, H.MBleg = hb;  H.MAleg = ha; end
            if o ~= 0
                H.bLP(end+1) = plot(ax,-180+o,0,'ro','MarkerFaceColor','r','MarkerSize',7,'PickableParts','none'); %#ok<AGROW>
            end
        end
        ch = ax.Children;  isB = ismember(ch,H.bLP);
        ax.Children = [ch(~isB); ch(isB)];      % bounds to the back
        rebuildLegends();
    end

    function drawBoundsT()
        delete(H.bT(isgraphics(H.bT)));   H.bT = gobjects(0);
        ax = H.axT;
        MAdB = 20*log10(S.Ma);  MBdB = 20*log10(S.Mb);
        wl = [max(1e-3,S.wp/100), min(1e3,S.wp*100)];
        H.bT(end+1) = patch(ax,[wl(1) wl(2) wl(2) wl(1)],[MAdB MAdB 200 200],col.MA, ...
            'FaceAlpha',0.07,'EdgeColor','none','PickableParts','none');
        H.bT(end+1) = patch(ax,[wl(1) S.wp S.wp wl(1)],[-500 -500 MBdB MBdB],col.MB, ...
            'FaceAlpha',0.08,'EdgeColor','none','PickableParts','none');
        H.bT(end+1) = plot(ax,wl,[MAdB MAdB],'--','Color',col.MA,'LineWidth',2);
        H.bT(end+1) = plot(ax,[wl(1) S.wp S.wp],[MBdB MBdB -500],'-','Color',col.MB,'LineWidth',2);
        H.bT(end+1) = text(ax,wl(1)*1.15,MAdB,sprintf('M_A = %.2f dB',MAdB), ...
            'VerticalAlignment','bottom','Color',col.MA);
        H.bT(end+1) = text(ax,wl(1)*1.15,MBdB-1,sprintf('M_B = %.2f dB, \\omega \\leq \\omega_p',MBdB), ...
            'VerticalAlignment','top','Color',col.MB);
        H.bT(end+1) = xline(ax,S.wp,':','Color',col.MB,'LineWidth',1.2,'Label',sprintf('\\omega_p = %.3g',S.wp), ...
            'LabelVerticalAlignment','bottom');
        ax.XLim = wl;
        ch = ax.Children;  isB = ismember(ch,H.bT);  ax.Children = [ch(~isB); ch(isB)];
        rebuildLegends();
    end

    function updatePlots(final)
        C = S.cur;  F = S.frozen;
        % ---------------- log-polar ----------------
        set(H.L,'XData',C.ph,'YData',C.mag);
        [xp,yp] = locusAt(C,S.wp);
        set(H.Lwp,'XData',xp,'YData',yp);
        set(H.LwpTxt,'Position',[xp yp 0]);
        if ~isempty(F)
            [xf,yf] = locusAt(F,S.wp);
            set(H.Lfwp,'XData',xf,'YData',yf);
        end
        if C.k == 0 && C.Kp ~= 0      % L(j0) is finite only for a Type-0 loop
            set(H.L0,'XData',-180*(C.Kp < 0),'YData',20*log10(abs(C.Kp)));
        else
            set(H.L0,'XData',NaN,'YData',NaN);
        end
        if final, autoXLim(); end

        % ---------------- closed-loop Bode ----------------
        set(H.T,'XData',S.w,'YData',C.Tmag);
        pkdB = 20*log10(C.MpT);
        if C.wpk > S.w(1)*1.01 && C.MpT > 1.0005
            set(H.TpkLine,'XData',[C.wpk C.wpk],'YData',[-500 pkdB]);
            H.TpkTxt.String = sprintf('\\omega_{peak} = %.3g rad/s, max |T(j\\omega)| = %.3f (%.2f dB)', ...
                C.wpk,C.MpT,pkdB);
        else
            set(H.TpkLine,'XData',NaN,'YData',NaN);
            H.TpkTxt.String = sprintf('No resonant peak: max |T(j\\omega)| = %.3f as \\omega \\rightarrow 0',C.MpT);
        end
        if final       % axis limits are only re-scaled when the interaction ends
            setIfChanged(H.axT,'YLim',[-24, min(40, max([10, 20*log10(S.Ma)+9, pkdB+7]))]);
        end
        updateGBode(final);

        % ---------------- step response ----------------
        ax = H.axY;
        yss = C.yss;  if ~isfinite(yss), yss = 1; end
        set(H.Y,'XData',C.t,'YData',C.y);
        if C.stable
            if ~isempty(H.Yunst.String), H.Yunst.String = ''; end
            setIfChanged(H.ylOS,'Value',(1+S.OS/100)*yss,'Label',sprintf('%%OS = %g%%',S.OS),'Visible','on');
            setIfChanged(H.ylP2,'Value',1.02*yss,'Visible','on');
            setIfChanged(H.ylM2,'Value',0.98*yss,'Visible','on');
            setIfChanged(H.xlTs,'Value',S.Ts,'Label',sprintf('t_s = %g s',S.Ts),'Visible','on');
            if isfinite(C.Ypk) && C.OS > 0.05
                set(H.Ypk,'XData',C.Tpk,'YData',C.Ypk);
                set(H.YpkTxt,'Position',[C.Tpk C.Ypk+0.02*yss 0],'String',sprintf('  %%OS = %.1f%%',C.OS));
            else
                set(H.Ypk,'XData',NaN,'YData',NaN);
                set(H.YpkTxt,'Position',[S.Ts*0.05 yss*1.03 0],'String','%OS = 0%');
            end
            if isfinite(C.TsAct)
                yts = interp1(C.t,C.y,C.TsAct);
                set(H.Yts,'XData',C.TsAct,'YData',yts);
                set(H.YtsTxt,'Position',[C.TsAct yts-0.03*yss 0],'String',sprintf('T_s = %.2f s',C.TsAct), ...
                    'HorizontalAlignment','center');
            else
                set(H.Yts,'XData',NaN,'YData',NaN);  set(H.YtsTxt,'String','');
            end
            if final
                tMax = max(2*S.Ts, min(C.t(end), 1.25*C.TsAct));
                if ~isempty(F) && F.stable && isfinite(F.TsAct), tMax = max(tMax, min(F.t(end),1.15*F.TsAct)); end
                yTop = max([1+1.8*S.OS/100, 1.15, 1.08*max(C.y(C.t<=tMax))/yss]);
                setIfChanged(ax,'XLim',[0 tMax],'YLim',[min(0,1.05*min(C.y)) , yTop*yss]);
            end
        else
            H.Yunst.String = 'Closed-loop system is UNSTABLE';
            set([H.ylOS H.ylP2 H.ylM2 H.xlTs],'Visible','off');
            set([H.Ypk H.Yts],'XData',NaN,'YData',NaN);  set([H.YpkTxt H.YtsTxt],'String','');
            setIfChanged(ax,'XLim',[0 2*S.Ts],'YLim',[-0.5 2]);
        end
    end

    function updateGBode(final)
        % Bode diagram of G(jw) with the characteristic frequencies of Sections 12.3-12.5:
        % PI zero frequency 1/T_i (|G| = sqrt(2)K, -45 deg) with the decade either side, and
        % the lead zero alpha, pole beta and w_max = sqrt(alpha*beta) (phase lead phi_max).
        C = S.cur;  F = S.frozen;
        set(H.Gm,'XData',S.w,'YData',C.Gmag);
        set(H.Gp,'XData',S.w,'YData',C.Gph);
        isTi = any(strcmp(S.type,{'PI','PID'}));
        isLead = any(strcmp(S.type,{'PD','PID'})) && S.phimax > 1e-6;
        KdB = 20*log10(S.K);
        z = 1/S.Ti;  a = NaN;  b = NaN;  wm = S.wmax;
        if isLead, [a,b] = leadAB(wm,S.phimax); end
        atWp = isLead && abs(log10(wm/S.wp)) < 1e-3;
        gx = struct('wp',S.wp,'z',z,'zlo',z/10,'zhi',10*z,'a',a,'wm',wm,'b',b);
        show = struct('wp',true,'z',isTi,'zlo',isTi,'zhi',isTi,'a',isLead,'wm',isLead,'b',isLead);
        lbl = struct('wp','\omega_p', 'z','1/T_i', 'zlo','1/(10T_i)', 'zhi','10/T_i', ...
            'a','\alpha', 'wm','\omega_{max}', 'b','\beta');
        if atWp, lbl.wp = '';  lbl.wm = '\omega_{max} = \omega_p'; end
        nm = fieldnames(gx);
        for k = 1:numel(nm)
            h = H.gx.(nm{k});
            if show.(nm{k})
                setIfChanged(h(1),'Value',gx.(nm{k}),'Label',lbl.(nm{k}),'Visible','on');
                setIfChanged(h(2),'Value',gx.(nm{k}),'Visible','on');
            else
                set(h,'Visible','off');
            end
        end
        setIfChanged(H.ylGK,'Value',KdB,'Label',sprintf('K = %.3g dB',KdB));
        % characteristic points: PI zero frequency and lead w_max
        pts = [];  txtM = {};  txtP = {};
        if isTi, pts(end+1) = z;  txtM{end+1} = ' \surd2K';  txtP{end+1} = ''; end
        if isLead, pts(end+1) = wm;  txtM{end+1} = ' K\surd(\beta/\alpha)';  txtP{end+1} = ''; end
        g = controllerResponse(pts);
        gm = 20*log10(abs(g));  gp = angle(g)*180/pi;
        for k = 1:numel(pts), txtP{k} = sprintf(' %.1f°',gp(k)); end
        set(H.GmPt,'XData',pts,'YData',gm);  set(H.GpPt,'XData',pts,'YData',gp);
        for k = 1:2
            if k <= numel(pts)
                set(H.GmTxt(k),'Position',[pts(k) gm(k) 0],'String',txtM{k});
                set(H.GpTxt(k),'Position',[pts(k) gp(k) 0],'String',txtP{k});
            else
                set([H.GmTxt(k) H.GpTxt(k)],'String','');
            end
        end
        if isLead
            Ghf = 20*log10(S.K*b/a);
            setIfChanged(H.ylGhf,'Value',Ghf,'Label',sprintf('G_{hf} = K\\beta/\\alpha = %.3g dB',Ghf),'Visible','on');
            setIfChanged(H.ylGphi,'Value',S.phimax,'Label',sprintf('\\phi_{max} = %.3g°',S.phimax),'Visible','on');
        else
            set([H.ylGhf H.ylGphi],'Visible','off');
        end
        switch S.type
            case 'P'
                s = 'G(s) = K: flat magnitude, no phase shift';
            case 'PI'
                s = sprintf(['|z| = 1/T_i = %.3g rad/s: G \\approx K/(sT_i) for \\omega \\leq %.3g, ' ...
                    'G \\approx K for \\omega \\geq %.3g'],z,z/10,10*z);
            otherwise
                if isLead
                    s = sprintf('\\alpha = %.3g, \\omega_{max} = \\surd(\\alpha\\beta) = %.3g, \\beta = %.3g rad/s',a,wm,b);
                else
                    s = '\alpha = \beta (\phi_{max} = 0): no phase lead';
                end
                if isTi, s = sprintf('%s;  1/T_i = %.3g rad/s',s,z); end
        end
        if ~strcmp(H.GinfoTxt.String,s), H.GinfoTxt.String = s; end
        if ~final, return; end
        % axis limits: cover the marked frequencies and the closed-loop frequency range
        fi = [S.wp/10, S.wp*10, pts];
        if isTi, fi = [fi z/10 10*z]; end
        if isLead, fi = [fi a b]; end
        xl = [max(S.w(1),min(fi)/3), min(S.w(end),max(fi)*3)];
        setIfChanged(H.axGm,'XLim',xl);
        in = S.w >= xl(1) & S.w <= xl(2);
        m = C.Gmag(in);  p = C.Gph(in);
        if ~isempty(F), m = [m F.Gmag(in)];  p = [p F.Gph(in)]; end
        ref = KdB;  if isLead, ref = 20*log10(S.K*b/a); end
        top = min(max(m), ref + 40);         % the PI integrator grows without bound as w -> 0
        yl = [min(floor(min(m)/5)*5, KdB) - 6, ceil(top/5)*5];
        if diff(yl) < 20, yl = mean(yl) + [-10 10]; end
        yl(2) = yl(2) + 0.3*diff(yl);        % headroom for the frequency labels
        setIfChanged(H.axGm,'YLim',yl);
        pl = [min(-10, floor(min(p)/45)*45), max(10, ceil(max(p)/45)*45)];
        setIfChanged(H.axGp,'YLim',pl + [-10 10],'YTick',-180:45:180);
    end

    function autoXLim()
        C = S.cur;  yl = H.axLP.YLim;
        in = C.mag > yl(1) & C.mag < yl(2);
        phs = C.ph(in);
        if ~isempty(S.frozen)
            F = S.frozen;  phs = [phs F.ph(F.mag > yl(1) & F.mag < yl(2))];
        end
        if isempty(phs), phs = -180; end
        xl = [min(-360, floor(min(phs)/90)*90), max(0, ceil(max(phs)/90)*90)];
        xl = [max(xl(1),-1080), min(xl(2),360)];
        if ~isequal(xl,H.axLP.XLim), H.axLP.XLim = xl; end
        span = diff(xl);
        if span <= 400, stp = 45; elseif span <= 800, stp = 90; else, stp = 180; end
        H.axLP.XTick = -1080:stp:360;
    end

    function rebuildLegends()
        if ~isfield(H,'MAleg') || ~isgraphics(H.MAleg), return; end
        frozen = ~isempty(S.frozen);
        if frozen, nmL = 'L_2(j\omega) current'; else, nmL = 'L(j\omega)'; end
        h = [H.MAleg H.MBleg H.contourLeg H.L];
        s = {'|T| \leq M_A (stay out)', '|T| \geq M_B, \omega \leq \omega_p (stay out)', ...
             '|T| contours (dB)', nmL};
        if frozen, h(end+1) = H.Lf;  s{end+1} = 'L_1(j\omega) frozen'; end
        h(end+1) = H.Lwp;  s{end+1} = 'L(j\omega_p)';
        if isfinite(S.KpReq) && S.KpReq > 0
            h(end+1) = H.ylKp;  s{end+1} = '|K_p|_{dB} (stay above)';
            h(end+1) = H.L0;    s{end+1} = 'L(j0)';
        end
        h(end+1) = H.crit; s{end+1} = 'critical point';
        lg = legend(H.axLP,h,s,'Location','southoutside','Orientation','horizontal','NumColumns',3);
        lg.AutoUpdate = 'off';
        if frozen
            legend(H.axT,[H.T H.Tf],{'|T_2(j\omega)| current','|T_1(j\omega)| frozen'}, ...
                'Location','southwest','AutoUpdate','off');
            legend(H.axGm,[H.Gm H.Gmf],{'G_2(j\omega) current','G_1(j\omega) frozen'}, ...
                'Location','best','AutoUpdate','off');
            if ~isempty(S.frozen) && S.frozen.stable
                legend(H.axY,[H.Y H.Yf],{'y_2(t) current','y_1(t) frozen'}, ...
                    'Location','southeast','AutoUpdate','off');
            else
                legend(H.axY,'off');
            end
        else
            legend(H.axT,'off');  legend(H.axGm,'off');  legend(H.axY,'off');
        end
    end

    function updateControls()
        setIfChanged(H.edK,'Value',S.K);        setIfChanged(H.slK,'Value',clamp(log10(S.K),-3,3));
        setIfChanged(H.edTi,'Value',S.Ti);      setIfChanged(H.slTi,'Value',clamp(log10(S.Ti),-2,3));
        setIfChanged(H.edW,'Value',S.wmax);     setIfChanged(H.slW,'Value',clamp(log10(S.wmax),-2,2));
        setIfChanged(H.edPhi,'Value',S.phimax); setIfChanged(H.slPhi,'Value',S.phimax);
        setIfChanged(H.cbLock,'Value',S.lockW);
    end

    function updateTable()
        C = S.cur;  F = S.frozen;
        names = {'Closed-loop stable'; 'max |T(jω)|'; 'min |T(jω)|, ω ≤ ω_p'; ...
                 'Peak frequency ω_peak'; 'Overshoot %OS'; 'Settling time T_s (2 %)'; ...
                 'Gain margin GM'; 'Phase margin PM'; 'High-freq. gain G_hf'; ...
                 sprintf('Ref. error e_R(∞), %s',lower(refName(S.refQ))); 'Dist. error e_D(∞)'};
        spec  = {'required'; sprintf('≤ M_A = %.4f',S.Ma); sprintf('≥ M_B = %.3g',S.Mb); ...
                 sprintf('ω_p = %.3g rad/s',S.wp); sprintf('≤ %g %%',S.OS); sprintf('≤ %g s',S.Ts); ...
                 '—'; '—'; 'small as possible'; essSpecStr(S.essR,'ref',S.refQ); essSpecStr(S.essD,'dist',0)};
        [vc,pc] = metricCol(C);
        if isempty(F)
            vf = repmat({'—'},11,1);  pf = NaN(11,1);
            cn = {'Metric','Specification','Current G(s)','Frozen'};
        else
            [vf,pf] = metricCol(F);
            cn = {'Metric','Specification','Current G₂(s)','Frozen G₁(s)'};
        end
        if ~isequal(cn(:),H.tbl.ColumnName(:)), H.tbl.ColumnName = cn; end
        D = [names spec vc vf];
        if ~isequal(D,H.tbl.Data), H.tbl.Data = D; end
        pat = [pc(:); pf(:)];
        if ~isequaln(pat,S.tblCache)           % restyle only when pass/fail pattern changes
            S.tblCache = pat;
            removeStyle(H.tbl);
            addStyle(H.tbl,H.stName,'column',1);
            ok  = [find(pc==1) 3*ones(nnz(pc==1),1); find(pf==1) 4*ones(nnz(pf==1),1)];
            bad = [find(pc==0) 3*ones(nnz(pc==0),1); find(pf==0) 4*ones(nnz(pf==0),1)];
            if ~isempty(ok),  addStyle(H.tbl,H.stOK,'cell',ok); end
            if ~isempty(bad), addStyle(H.tbl,H.stBad,'cell',bad); end
        end
    end

    function [v,p] = metricCol(C)
        v = cell(11,1);  p = NaN(11,1);
        minTB = min(C.Tabs(S.w <= S.wp));
        v{1} = yesno(C.stable);  p(1) = C.stable;
        v{2} = sprintf('%.4f (%.2f dB)',C.MpT,20*log10(C.MpT));  p(2) = C.MpT <= S.Ma*1.0005;
        v{3} = sprintf('%.4f',minTB);  p(3) = minTB >= S.Mb*0.9995;
        v{4} = sprintf('%.3g rad/s',C.wpk);
        if C.stable
            v{5} = sprintf('%.2f %%',C.OS);   p(5) = C.OS <= S.OS + 1e-6;
            if isfinite(C.TsAct), v{6} = sprintf('%.3f s',C.TsAct); else, v{6} = sprintf('> %.3g s',C.t(end)); end
            p(6) = isfinite(C.TsAct) && C.TsAct <= S.Ts + 1e-6;
            kn = {'K_p','K_v','K_a'};
            if C.k > S.refQ
                v{10} = sprintf('0 (Type-%d)',C.k);
            elseif C.k == S.refQ
                v{10} = sprintf('%.4g (%s = %.4g)',C.eR,kn{S.refQ+1},C.Kq);
            else
                v{10} = sprintf('∞ (Type-%d)',C.k);
            end
            if isfinite(S.essR), p(10) = C.eR <= S.essR + 1e-9; end
            if isinf(C.Gdc), v{11} = '0 (G has integrator)'; else, v{11} = sprintf('%.4g',C.eD); end
            if isfinite(S.essD), p(11) = abs(C.eD) <= S.essD + 1e-9; end
        else
            v{5} = '—';  v{6} = '—';  p(5) = 0;  p(6) = 0;  v{10} = '—';  v{11} = '—';
            if isfinite(S.essR), p(10) = 0; end
            if isfinite(S.essD), p(11) = 0; end
        end
        if isinf(C.Gm), v{7} = '∞';
        elseif C.Gm > 0 && C.Wcg > 0, v{7} = sprintf('%.2f dB @ %.3g rad/s',20*log10(C.Gm),C.Wcg);
        else, v{7} = 'n/a'; end
        if isfinite(C.Pm), v{8} = sprintf('%.1f° @ %.3g rad/s',C.Pm,C.Wcp); else, v{8} = '∞'; end
        v{9} = sprintf('%.4g',C.Ghf);
    end

    function updateStatus()
        [~,p] = metricCol(S.cur);
        lbl = {'stable','|T| ≤ M_A','|T| ≥ M_B for ω ≤ ω_p','','%OS','T_s','','','','e_R(∞)','e_D(∞)'};
        fails = lbl(p==0);
        if isempty(fails)
            setIfChanged(H.status,'Text','✔ The current design meets all closed-loop specifications', ...
                'FontColor',col.ok);
        else
            setIfChanged(H.status,'Text',['✘ Not yet met: ' strjoin(fails,',  ') ...
                '  (drag the black L(jω) locus or use the sliders)'],'FontColor',col.bad);
        end
    end

    function updateInfo()
        % Derived values and design hints shown beside the controls they concern.
        H.lblForm.Text = controllerTex();
        H.lblForm.FontSize = 14 - 2*strcmp(S.type,'PID');   % the PID equation is the widest
        if any(strcmp(S.type,{'PD','PID'}))
            if S.phimax > 1e-6
                [a,b] = leadAB(S.wmax,S.phimax);
                H.lblAB.Text = sprintf('α = ω_max/tan((φ_max+π/2)/2) = %.4g,   β = ω_max²/α = %.4g',a,b);
            else
                H.lblAB.Text = 'φ_max = 0, so α = β (no phase lead)';
            end
            [need,wAt] = requiredLead();
            if need < 0.05
                H.lblLead.Text = 'Without lead, L(jω) already avoids the M_A region: no phase lead is needed (Δφ = 0°).';
            else
                H.lblLead.Text = sprintf(['Without lead, L(jω) enters the M_A region. Lead needed: Δφ ≈ %.1f° ' ...
                    '(deepest at ω = %.3g rad/s). Place it at ω_max = ω_p and add ≈10°, since the lead ' ...
                    'also raises |L|.'],need,wAt);
            end
        end
        H.lblEss.Text = essHints();
        if isempty(S.frozen)
            H.lblFrz.Text = 'No frozen design.';
        else
            H.lblFrz.Text = ['Frozen: ' strrep(S.frozen.desc,'G(s)','G₁(s)')];
        end
    end

    function txt = essHints()
        % One line per steady-state error requirement: what it needs and whether it is met.
        C = S.cur;  q = S.refQ;
        kn = {'K_p','K_v','K_a'};
        txt = {};
        if isfinite(S.essR)
            Kreq = errorConstantRequired(q,S.essR);
            if S.essR == 0
                need = sprintf('L(s) of Type ≥ %d',q+1);
            elseif isnan(Kreq)
                need = 'any stable loop';
            elseif q == 0
                need = sprintf('K_p ≥ %.3g (L(j0) ≥ %.3g dB)',Kreq,20*log10(Kreq));
            else
                need = sprintf('%s ≥ %.3g',kn{q+1},Kreq);
            end
            if C.eR <= S.essR + 1e-9
                act = '✔';
            elseif C.k == q && S.essR > 0 && C.Kq > 0
                act = sprintf('✘ now %s = %.3g → K ≥ %.4g',kn{q+1},C.Kq,Kreq*S.K/C.Kq);
            else
                act = sprintf('✘ L(s) is Type-%d → add an integrator',C.k);
            end
            txt{end+1} = sprintf('Ref. (%s): needs %s  %s',lower(refName(q)),need,act);
        end
        if isfinite(S.essD)
            if S.essD == 0
                need = 'an integrator in G(s)';
            else
                need = sprintf('|1/P(0) + G(0)| ≥ %.3g',1/S.essD);
            end
            if abs(C.eD) <= S.essD + 1e-9
                act = '✔';
            elseif S.essD > 0 && C.kG == 0 && C.Gdc ~= 0 && (1/S.essD - 1/C.Pdc)/(C.Gdc/S.K) > 0
                act = sprintf('✘ now e_D = %.3g → K ≥ %.4g',C.eD,(1/S.essD - 1/C.Pdc)/(C.Gdc/S.K));
            else
                act = '✘ use PI or PID';
            end
            txt{end+1} = sprintf('Dist.: needs %s  %s',need,act);
        end
        if isempty(txt), txt = {'No steady-state error requirements set (Inf).'}; end
    end

    function str = controllerTex()
        % Controller as one LaTeX equation: general form = numeric values, as in the notes.
        f = @(v) sprintf('%.3g',v);
        str = f(S.K);
        if any(strcmp(S.type,{'PD','PID'})) && S.phimax > 1e-6
            [a,b] = leadAB(S.wmax,S.phimax);
            str = [str '\,\frac{1+s/' f(a) '}{1+s/' f(b) '}'];
        end
        if any(strcmp(S.type,{'PI','PID'}))
            str = [str '\,\frac{1+' f(S.Ti) 's}{' f(S.Ti) 's}'];
        end
        str = ['$G(s)=' S.formTex '=' str '$'];
    end

    function str = controllerStr()
        % Numeric controller in the notes' parameterisation.
        f = @(v) sprintf('%.4g',v);
        if any(strcmp(S.type,{'PD','PID'})) && S.phimax > 1e-6
            [a,b] = leadAB(S.wmax,S.phimax);
            lead = sprintf('(1 + s/%s)/(1 + s/%s)',f(a),f(b));
        else
            lead = '';
        end
        pi_ = sprintf('(1 + %s s)/(%s s)',f(S.Ti),f(S.Ti));
        switch S.type
            case 'P',   str = ['G(s) = ' f(S.K)];
            case 'PI',  str = ['G(s) = ' f(S.K) ' ' pi_];
            case 'PD',  str = strtrim(['G(s) = ' f(S.K) ' ' lead]);
            case 'PID', str = strtrim(['G(s) = ' f(S.K) ' ' lead ' ' pi_]);
        end
    end

    function updateMethodText()
        hdr = {['Problem:  ' S.exNote], ''};
        switch S.type
            case 'P'
                body = {
                '12.2.5  Proportional controller design,  G(s) = K'
                ''
                '1. Compute M_A, M_B and ω_p from %OS and T_s (shown under the specifications).'
                '2. K only shifts the L(jω) locus UP (K > 1) or DOWN (K < 1); the phase is unaltered.'
                '   Drag the locus up/down (or move the K slider) until:'
                '   •  L(jω) stays outside the blue M_A region for ALL ω  (|T| ≤ M_A, overshoot);'
                '   •  L(jω) stays above the green M_B region for ω ≤ ω_p, i.e. the green L(jω_p)'
                '      marker sits on/above the green line  (|T| ≥ M_B, settling time).'
                '3. Prefer the SMALLEST K that meets both bounds: it minimises the high-frequency'
                '   controller gain G_hf = K (less noise on the control action, "cheaper" control).'
                '4. Always verify with the step response — the bounds only approximate the'
                '   time-domain specifications.'
                ''
                'Limitation: a P controller is Type-0. If the locus cannot be shifted to satisfy both'
                'bounds, a higher-order controller (PI / PD / PID) is needed.'};
            case 'PI'
                body = {
                '12.3.3  PI controller design,  G(s) = K(1 + sT_i)/(sT_i)'
                ''
                'Use a PI controller when the type number of L(s) must be increased (zero step error)'
                'or plant input disturbances must be fully rejected at steady state.'
                ''
                '1. Set T_i LARGE (e.g. 100) so the zero 1/T_i is very low and G(s) ≈ K for'
                '   ω ≥ 10/T_i  (press "Step 1: start design").'
                '2. Design K exactly as for a P controller: drag the locus up/down until it is'
                '   outside the M_A region and L(jω_p) is above the green M_B region.'
                '3. Now DECREASE T_i (drag the locus LEFT, or use the slider). Smaller T_i gives'
                '   faster integral action but more phase lag over a wider frequency range.'
                '   Stop when the locus approaches the M_A boundary.'
                '4. Check the step response; adjust K or T_i if T_s or %OS is not met.'};
            case 'PD'
                body = {
                '12.4.3  PD (lead) controller design,  G(s) = K(1 + s/α)/(1 + s/β),  α < β'
                ''
                '1. Set α = β (φ_max = 0) so that G(s) = K  (press "Step 1: start design").'
                '2. Design K (drag up/down) to meet the M_B ≤ |T(jω)| constraint with sufficiently'
                '   low gain, i.e. place L(jω_p) on/above the stay-above (M_B) boundary.'
                '3. If L(jω) still enters the blue M_A region, add phase lead at ω_max = ω_p'
                '   (the frequency expected to sit closest to the M_A region).'
                '   Measure the phase lead φ_max needed to move the locus out of the region and add a'
                '   safety margin (≈10°). The lead filter also increases the gain at ω_max to'
                '        |G(jω_max)| = |K| √(β/α),'
                '   so the point moves RIGHT (phase lead) and UP (increased gain) in the log-polar'
                '   plane.  Drag the locus RIGHT, or use the φ_max slider.'
                '4. α = ω_max / tan((φ_max + π/2)/2),   β = ω_max² / α,   ω_max = √(αβ).'
                '   The controller Bode diagram marks α, ω_max and β, with |G(jω_max)| = K√(β/α).'
                '5. Re-adjust K; check the step response. Note G_hf = Kβ/α > K (noise trade-off).'};
            case 'PID'
                body = {
                '12.5.3  PID controller design,  G(s) = K(1 + s/α)(1 + T_i s) / (sT_i(1 + s/β))'
                ''
                'Step 1: Set T_i ≫ K (large T_i), so G(s) ≈ K(1 + s/α)/(1 + s/β) — a PD controller.'
                'Step 2: Set K so that the design frequency point L(jω_p) sits near the critical'
                '        point, so that the phase lead required at mid frequencies is easily read off.'
                'Step 3: Select {K, α, β} as in §12.4.3 (ω_max = ω_p, φ_max = measured lead +'
                '        margin).  Drag mode "K + φ_max" lets you drag the locus RIGHT to add lead.'
                'Step 4: Continually REDUCE T_i (drag mode "K + T_i", drag LEFT) until the locus is'
                '        close to the design boundaries, leaving a small safety margin.'
                ''
                'The stay-above formulation for a Type-1+ controller (M_B = 0.98 for ω ≤ ω_p) is used.'};
        end
        tips = {'', '—  How to use  —', ...
            '•  Hover over the black L(jω) locus: the cursor becomes a hand. Click and drag it.', ...
            '•  "Freeze design" stores the current design as G₁(s) (orange, dashed) in all plots;', ...
            '   carry on designing G₂(s) and compare the two in the plots and the table.', ...
            '•  Grey dashed curves in the log-polar plot are contours of constant |T(jω)| in dB.', ...
            '•  Reference error requirement (Chapter 10, §12.2.4): for a unit step, ramp or parabola,', ...
            '   e_R(∞) = 1/(1 + K_p), 1/K_v or 1/K_a. For a step, the blue L(j0) marker must sit on or', ...
            '   above the dashed |K_p|_dB line (K_p = 1/e_max − 1). e_max = 0 needs L(s) to be at least', ...
            '   Type-1, -2 or -3 respectively.', ...
            '•  Disturbance error requirement (§10.8): for a unit step disturbance at the plant input,', ...
            '   e_D(∞) = −lim 1/(1/P(s) + G(s)). Full rejection (e_max = 0) needs an integrator in G(s),', ...
            '   whatever the type of P(s), so use a PI or PID controller.'};
        H.txtMethod.Value = [hdr(:); body(:); tips(:)];
    end

%% =====================================================================
%  Helpers
%  =====================================================================
    function [x,y] = locusAt(C,wq)
        lw = log10(S.w);
        x = interp1(lw,C.ph,log10(wq));
        y = interp1(lw,C.mag,log10(wq));
    end

    function phim = solvePhimax(w,wm,target)
        lo = 0;  hi = 85;
        if target <= leadPhase(w,wm,lo), phim = lo; return; end
        if target >= leadPhase(w,wm,hi), phim = hi; return; end
        for it = 1:40
            mid = (lo+hi)/2;
            if leadPhase(w,wm,mid) < target, lo = mid; else, hi = mid; end
        end
        phim = (lo+hi)/2;
    end
end

%% =========================================================================
%  Helper functions
%  =========================================================================
function [a,b] = leadAB(wm,phimaxDeg)
% Section 12.4.3:  alpha = w_max / tan((phi_max + pi/2)/2),  beta = w_max^2/alpha
a = wm/tan((phimaxDeg*pi/180 + pi/2)/2);
b = wm^2/a;
end

function p = leadPhase(w,wm,phimaxDeg)
if phimaxDeg <= 0, p = 0; return; end
[a,b] = leadAB(wm,phimaxDeg);
p = atand(w/a) - atand(w/b);
end

function [x,y] = mContour(M)
% Contour of constant |T(jw)| = M in the log-polar plane (as in the notes):
% 1/L = -1 + (1/M)e^{j phi}
phi = linspace(0,2*pi,2500);
Kc  = -1 + exp(1i*phi)/M;
y   = -20*log10(abs(Kc));
x   = angle(Kc)*180/pi;
x(x > 0) = x(x > 0) - 360;
x = x(2:end-1);  y = y(2:end-1);
y(~isfinite(y)) = NaN;
end

function K = errorConstantRequired(q,ess)
% Error constant needed for e(inf) <= ess with a unit step (q = 0, K_p >= 1/e - 1),
% ramp (q = 1, K_v >= 1/e) or parabola (q = 2, K_a >= 1/e). NaN when not applicable.
K = NaN;
if ~isfinite(ess) || ess <= 0, return, end
if q == 0
    if ess < 1, K = 1/ess - 1; end
else
    K = 1/ess;
end
end

function s = refName(q)
names = {'Step','Ramp','Parabola'};
s = names{q+1};
end

function K = limGain(sys,j)
% lim_{s->0} s^j sys(s), e.g. K_p (j = 0), K_v (j = 1), K_a (j = 2).
[k,Kk] = typeAndGain(sys);
if Kk == 0
    K = 0;
elseif j < k
    K = Inf*sign(Kk);
elseif j > k
    K = 0;
else
    K = Kk;
end
end

function s = essSpecStr(ess,kind,q)
if ~isfinite(ess)
    s = '—';
elseif ess == 0 && strcmp(kind,'ref')
    s = sprintf('= 0 (L Type ≥ %d)',q+1);
elseif ess == 0
    s = '= 0 (G Type ≥ 1)';
elseif strcmp(kind,'ref')
    s = sprintf('≤ %.4g',ess);
else
    s = sprintf('|e_D| ≤ %.4g',ess);
end
end

function [k,Kk] = typeAndGain(sys)
% System type k (net number of poles at the origin) and Kk = lim s^k sys(s).
[z,p,g] = zpkdata(zpk(sys),'v');
tol = 1e-6;
zo = abs(z) < tol;
po = abs(p) < tol;
k = sum(po) - sum(zo);
Kk = real(g*prod(-z(~zo))/prod(-p(~po)));
end

function st = clStable(T)
try
    if hasdelay(T), T = pade(T,6); end
    st = all(real(pole(T)) < -1e-9);
catch
    st = false;
end
end

function sys = parseTF(str)
% Evaluate a MATLAB expression in s as a transfer function.
str = strtrim(str);
if isempty(str), error('Transfer function is empty.'); end
f = str2func(['@(s) ' str]);
sys = tf(f(tf('s')));
if ~isequal(size(sys),[1 1]), error('P(s) must be a SISO transfer function.'); end
end

function styleAx(ax)
grid(ax,'on');  hold(ax,'on');  box(ax,'on');
disableDefaultInteractivity(ax);
end

function setIfChanged(h,varargin)
% Set properties only when their value actually changes (avoids needless redraws).
for k = 1:2:numel(varargin)
    old = h.(varargin{k});  new = varargin{k+1};
    if isnumeric(new) && isnumeric(old) && isequal(size(old),size(new))
        same = all(abs(old(:) - new(:)) <= 1e-9*max(1,abs(new(:))));
    else
        same = isequal(old,new);
    end
    if ~same, h.(varargin{k}) = new; end
end
end

function v = clamp(v,lo,hi)
v = min(max(v,lo),hi);
end

function s = onoff(b)
if b, s = 'on'; else, s = 'off'; end
end

function s = yesno(b)
if b, s = 'Yes'; else, s = 'No'; end
end

function setVis(h,b)
for k = 1:numel(h), h{k}.Visible = onoff(b); end
end

function h = at(h,row,col)
% Place a component in a grid layout cell (row, col may be spans like [1 2]).
h.Layout.Row = row;
h.Layout.Column = col;
end

function EX = exampleList()
% Worked examples from Chapter 12 (values as used in the notes' code).
% Steady-state error requirements (Inf = none): refQ selects the reference
% (0 step, 1 ramp, 2 parabola) for the limit essR; essD limits |e_D| for a step
% disturbance at the plant input.
mk = @(name,Pstr,OS,Ts,type,final,note,refQ,essR,essD) struct('name',name,'Pstr',Pstr, ...
    'OS',OS,'Ts',Ts,'type',type,'final',final,'note',note,'refQ',refQ,'essR',essR,'essD',essD);
EX = mk('Ex 12.2.5 (P): P = 10/(s(s+2))','10/(s*(s+2))',25,5,'P',struct('K',0.6), ...
    'Design a proportional controller for P(s) = 10/(s(s+2)) which satisfies a settling time of 5 s and a percentage overshoot of 25 %.',0,Inf,Inf);
EX(end+1) = mk('Ex 12.3.3(1) (PI): P = 1/(s(s+2))','1/(s*(s+2))',25,5,'PI',struct('K',4,'Ti',25), ...
    'Design a first-order controller for P(s) = 1/(s(s+2)): T_s = 5 s, %OS = 25 %, and fully reject input disturbances at steady state.',0,Inf,0);
EX(end+1) = mk('Ex 12.3.3(2) (PI): P = 0.5/(1+s)','0.5/(1+s)',10,10,'PI',struct('K',1,'Ti',0.5), ...
    'Design a feedback controller for P(s) = 0.5/(1+s) giving zero-error step tracking at steady state, T_s = 10 s and %OS = 10 %.',0,0,Inf);
EX(end+1) = mk('Ex 12.4.3 (PD/lead): P = 1/s^2','1/s^2',25,5,'PD',struct('K',1.5,'phimax',55), ...
    'Design a controller for P(s) = 1/s^2: T_s = 5 s, %OS = 25 %, zero-error tracking of step and ramp references.',1,0,Inf);
EX(end+1) = mk('Ex 12.5.3 (PID): P = 1/(s^2(s/10+1))','1/(s^2*(s/10+1))',25,5,'PID',struct('K',0.65,'phimax',70,'Ti',5), ...
    'Design a controller for P(s) = 1/(s^2(s/10+1)): T_s = 5 s, %OS = 25 %, zero-error tracking for step-like disturbances.',0,Inf,0);
EX(end+1) = mk('Ex 12.2.3 (margins): P = 10/(s(1+s/2)(1+s/5))','10/(s*(1+s/2)*(1+s/5))',25,5,'P',[], ...
    'Plant from the margins-of-stability example (PM = 45°, GM = 6 dB). Here the tracking bounds use %OS = 25 % and T_s = 5 s; change them as required.',0,Inf,Inf);
EX(end+1) = mk('Ex 12.2.4 (step error): P = 5e^{-0.01s}/(1+s/12)','5*exp(-0.01*s)/(1+s/12)',25,5,'P',struct('K',1.8), ...
    ['Design a proportional controller that results in a steady-state error e(inf) <= 0.1 for P(s) = 5e^(-0.01s)/(1+s/12): ' ...
    'K_p = 1/0.1 - 1 = 9, so L(j0) must lie on or above |K_p|_dB = 19.1 dB (K = 1.8). The %OS and T_s bounds are extra here; change them as required.'],0,0.1,Inf);
end
